window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-704f310fb3c34acb"]={"versions": [{"id": "FIG-704f310fb3c34acb", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Komponentendiagramm / Schnittstellendiagramm der AUTOSAR Adaptive Platform zur Darstellung der Abhängigkeiten des funktionalen Clusters <strong>Time Synchronization</strong> von externen Schnittstellen und Clustern innerhalb der Plattformarchitektur.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\"><strong>Komponenten / Funktionale Cluster:</strong></p>\n<ul class=\"fig-list\">\n<li><code>Time Synchronization</code> («aapFunctionalCluster», daemon-based): Konsument aller definierten Schnittstellen über gestrichelte Abhängigkeitspfeile mit Stereotyp «use».</li>\n<li><code>Operating System</code>: Realisiert über Realisierungspfeil (gestrichelte Linie mit geschlossener, nicht ausgefüllter Dreiecksspitze) die Schnittstelle <code>Raw Socket API</code>.</li>\n<li><code>Log and Trace</code> («aapFunctionalCluster»): Realisiert die Schnittstelle <code>Log and Trace::Logger</code>.</li>\n<li><code>Persistency</code> («aapFunctionalCluster»): Realisiert die Schnittstelle <code>Persistency::KeyValueStorage</code>.</li>\n</ul>\n<p class=\"fig-p\"><strong>Schnittstellen und Operationen:</strong></p>\n<ul class=\"fig-list\">\n<li><code>Raw Socket API</code> («aapInternal»): Betriebssystemnahe Schnittstelle ohne explizit aufgelistete Methoden.</li>\n<li><code>Log and Trace::Logger</code> («aapAPI,aapNativeInterface»):</li>\n<li><code>+ IsEnabled()</code></li>\n<li><code>+ Log(MsgId, Params)</code></li>\n<li><code>+ LogDebug(): LogStream</code></li>\n<li><code>+ LogError(): LogStream</code></li>\n<li><code>+ LogFatal(): LogStream</code></li>\n<li><code>+ LogInfo(): LogStream</code></li>\n<li><code>+ LogVerbose(): LogStream</code></li>\n<li><code>+ LogWarn(): LogStream</code></li>\n<li><code>+ WithLevel(): LogStream</code></li>\n<li><code>Persistency::KeyValueStorage</code> («aapAPI,aapPortInterface»):</li>\n<li><code>+ DiscardPendingChanges()</code></li>\n<li><code>+ GetAllKeys()</code></li>\n<li><code>+ GetValue()</code></li>\n<li><code>+ KeyExists()</code></li>\n<li><code>+ RecoverKey()</code></li>\n<li><code>+ RemoveAllKeys()</code></li>\n<li><code>+ RemoveKey()</code></li>\n<li><code>+ ResetKey()</code></li>\n<li><code>+ SetValue()</code></li>\n<li><code>+ SyncToStorage()</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Architekturdiagramm ohne Darstellung von Laufzeitsequenzen oder Protokollabläufen. Die gerichteten «use»-Abhängigkeiten modellieren synchrone bzw. funktionale Aufrufbeziehungen vom <code>Time Synchronization</code>-Daemon in Richtung der Schnittstellen des Betriebssystems (<code>Raw Socket API</code> für Netzwerkzeit-Paketübertragung), des Loggings (<code>Logger</code> für Status- und Fehlerausgaben) und der Zustandsspeicherung (<code>KeyValueStorage</code> für persistente Zeitsynchronisationsparameter).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><code>Time Synchronization</code> ist architektonisch als Daemon-basierter Cluster konzipiert.</li>\n<li>Zur Netzwerkanbindung für Zeitsynchronisationsprotokolle (z. B. gPTP/IEEE 802.1AS) greift der Daemon direkt auf interne Raw-Sockets des Betriebssystems (<code>Raw Socket API</code>) zu.</li>\n<li><code>KeyValueStorage</code> wird über ein Service- bzw. Port-Interface («aapPortInterface») angebunden, während das Logging über eine plattformnative C++-API («aapNativeInterface») erfolgt.</li>\n</ul>"}, {"id": "FIG-9230af3e70a5249a", "releases": ["R22-11", "R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Komponentendiagramm / Schnittstellendiagramm der AUTOSAR Adaptive Platform zur Darstellung der Abhängigkeiten des funktionalen Clusters <strong>Time Synchronization</strong> von externen Schnittstellen und Clustern innerhalb der Plattformarchitektur.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\"><strong>Komponenten / Funktionale Cluster:</strong></p>\n<ul class=\"fig-list\">\n<li><code>Time Synchronization</code> («aapFunctionalCluster», daemon-based): Konsument aller definierten Schnittstellen über gestrichelte Abhängigkeitspfeile mit Stereotyp «use».</li>\n<li><code>Operating System</code>: Realisiert über Realisierungspfeil (gestrichelte Linie mit geschlossener, nicht ausgefüllter Dreiecksspitze) die Schnittstelle <code>Raw Socket API</code>.</li>\n<li><code>Log and Trace</code> («aapFunctionalCluster»): Realisiert die Schnittstelle <code>Log and Trace::Logger</code>.</li>\n<li><code>Persistency</code> («aapFunctionalCluster»): Realisiert die Schnittstelle <code>Persistency::KeyValueStorage</code>.</li>\n</ul>\n<p class=\"fig-p\"><strong>Schnittstellen und Operationen:</strong></p>\n<ul class=\"fig-list\">\n<li><code>Raw Socket API</code> («aapInternal»): Betriebssystemnahe Schnittstelle ohne explizit aufgelistete Methoden.</li>\n<li><code>Log and Trace::Logger</code> («aapAPI,aapNativeInterface»):</li>\n<li><code>+ IsEnabled()</code></li>\n<li><code>+ Log(MsgId, Params)</code></li>\n<li><code>+ LogDebug(): LogStream</code></li>\n<li><code>+ LogError(): LogStream</code></li>\n<li><code>+ LogFatal(): LogStream</code></li>\n<li><code>+ LogInfo(): LogStream</code></li>\n<li><code>+ LogVerbose(): LogStream</code></li>\n<li><code>+ LogWarn(): LogStream</code></li>\n<li><code>+ WithLevel(): LogStream</code></li>\n<li><code>Persistency::KeyValueStorage</code> («aapAPI,aapPortInterface»):</li>\n<li><code>+ DiscardPendingChanges()</code></li>\n<li><code>+ GetAllKeys()</code></li>\n<li><code>+ GetValue()</code></li>\n<li><code>+ KeyExists()</code></li>\n<li><code>+ RecoverKey()</code></li>\n<li><code>+ RemoveAllKeys()</code></li>\n<li><code>+ RemoveKey()</code></li>\n<li><code>+ ResetKey()</code></li>\n<li><code>+ SetValue()</code></li>\n<li><code>+ SyncToStorage()</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Architekturdiagramm ohne Darstellung von Laufzeitsequenzen oder Protokollabläufen. Die gerichteten «use»-Abhängigkeiten modellieren synchrone bzw. funktionale Aufrufbeziehungen vom <code>Time Synchronization</code>-Daemon in Richtung der Schnittstellen des Betriebssystems (<code>Raw Socket API</code> für Netzwerkzeit-Paketübertragung), des Loggings (<code>Logger</code> für Status- und Fehlerausgaben) und der Zustandsspeicherung (<code>KeyValueStorage</code> für persistente Zeitsynchronisationsparameter).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><code>Time Synchronization</code> ist architektonisch als Daemon-basierter Cluster konzipiert.</li>\n<li>Zur Netzwerkanbindung für Zeitsynchronisationsprotokolle (z. B. gPTP/IEEE 802.1AS) greift der Daemon direkt auf interne Raw-Sockets des Betriebssystems (<code>Raw Socket API</code>) zu.</li>\n<li><code>KeyValueStorage</code> wird über ein Service- bzw. Port-Interface («aapPortInterface») angebunden, während das Logging über eine plattformnative C++-API («aapNativeInterface») erfolgt.</li>\n</ul>"}, {"id": "FIG-9002b7d402773fe9", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Komponentendiagramm / Schnittstellendiagramm der AUTOSAR Adaptive Platform zur Darstellung der Abhängigkeiten des funktionalen Clusters <strong>Time Synchronization</strong> von externen Schnittstellen, Plattform-Clustern und kryptografischen Diensten innerhalb der Plattformarchitektur.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\"><strong>Komponenten / Funktionale Cluster:</strong></p>\n<ul class=\"fig-list\">\n<li><code>Time Synchronization</code> («aapFunctionalCluster», daemon-based): Verwendet die Schnittstellen über «use»-Abhängigkeiten; an der Verbindung zu <code>KeyValueStorage</code> ist zusätzlich der Stereotyp «aapRequiredPort» annotiert.</li>\n<li><code>Operating System</code>: Realisiert die Schnittstelle <code>Raw Socket API</code>.</li>\n<li><code>Log and Trace</code> («aapFunctionalCluster»): Realisiert die Schnittstelle <code>Logger</code>.</li>\n<li><code>Persistency</code> («aapFunctionalCluster»): Realisiert die Schnittstelle <code>KeyValueStorage</code>.</li>\n<li><code>Cryptography</code> («aapFunctionalCluster», daemon-based): Realisiert die Schnittstelle <code>CryptoStack</code>.</li>\n</ul>\n<p class=\"fig-p\"><strong>Schnittstellen und Operationen:</strong></p>\n<ul class=\"fig-list\">\n<li><code>Raw Socket API</code> («aapInternal»): Interne OS-Schnittstelle ohne aufgeführte Methoden.</li>\n<li><code>Logger</code> («aapAPI,aapNativeInterface»):</li>\n<li><code>+ IsEnabled(): bool</code></li>\n<li><code>+ Log(MsgId, Params)</code></li>\n<li><code>+ LogDebug(): LogStream</code></li>\n<li><code>+ LogError(): LogStream</code></li>\n<li><code>+ LogFatal(): LogStream</code></li>\n<li><code>+ LogInfo(): LogStream</code></li>\n<li><code>+ LogVerbose(): LogStream</code></li>\n<li><code>+ LogWarn(): LogStream</code></li>\n<li><code>+ WithLevel(): LogStream</code></li>\n<li><code>KeyValueStorage</code> («aapAPI,aapPortInterface»):</li>\n<li><code>+ DiscardPendingChanges()</code></li>\n<li><code>+ GetAllKeys()</code></li>\n<li><code>+ GetCurrentValueSize()</code></li>\n<li><code>+ GetValue()</code></li>\n<li><code>+ KeyExists()</code></li>\n<li><code>+ RecoverKey()</code></li>\n<li><code>+ RemoveAllKeys()</code></li>\n<li><code>+ RemoveKey()</code></li>\n<li><code>+ ResetKey()</code></li>\n<li><code>+ SetValue()</code></li>\n<li><code>+ SyncToStorage()</code></li>\n<li><code>CryptoStack</code> («aapAPI,aapNativeInterface»): Native Kryptografie-Schnittstelle ohne explizit aufgelistete Methoden.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Architekturdiagramm ohne Darstellung von Laufzeitsequenzen oder Protokollabläufen. Die gerichteten «use»-Abhängigkeiten modellieren synchrone bzw. funktionale Aufrufbeziehungen vom <code>Time Synchronization</code>-Daemon in Richtung der Schnittstellen des Betriebssystems (<code>Raw Socket API</code> für Netzwerkzeit-Paketübertragung), des Loggings (<code>Logger</code> für Status- und Fehlerausgaben) und der Zustandsspeicherung (<code>KeyValueStorage</code> für persistente Zeitsynchronisationsparameter).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><code>Time Synchronization</code> setzt für kryptografische Funktionen (z. B. Authentifizierung und Absicherung von Zeitprotokollnachrichten) auf die native Schnittstelle <code>CryptoStack</code> des Daemon-basierten Clusters <code>Cryptography</code>.</li>\n<li>Der Zugriff auf <code>KeyValueStorage</code> ist formal als Port-Interface über einen Required Port («aapRequiredPort») modelliert.</li>\n<li>Die Methode <code>GetCurrentValueSize()</code> ermöglicht die Bestimmung von Nutzdatengrößen vor dem Auslesen aus dem persistenten Speicher.</li>\n<li><code>IsEnabled(): bool</code> spezifiziert explizit einen booleschen Rückgabewert zur Prüfung des Logging-Zustands.</li>\n</ul>"}, {"id": "FIG-4975a7f23e5f4a80", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Komponentendiagramm / Schnittstellendiagramm der AUTOSAR Adaptive Platform zur Darstellung der Abhängigkeiten des funktionalen Clusters <strong>Time Synchronization</strong> von Betriebs-, Persistenz-, Logging-, Krypto- und Ausführungsmanagement-Diensten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\"><strong>Komponenten / Funktionale Cluster:</strong></p>\n<ul class=\"fig-list\">\n<li><code>Time Synchronization</code> («aapFunctionalCluster», daemon-based): Verwendet alle Schnittstellen über «use»-Abhängigkeiten; an der Beziehung zu <code>KeyValueStorage</code> ist «aapRequiredPort» annotiert.</li>\n<li><code>Operating System</code>: Realisiert die Schnittstelle <code>Raw Socket API</code>.</li>\n<li><code>Log and Trace</code> («aapFunctionalCluster»): Realisiert die Schnittstelle <code>Logger</code>.</li>\n<li><code>Execution Management</code> («aapFunctionalCluster», daemon-based): Realisiert die Schnittstelle <code>ExecutionClient</code>.</li>\n<li><code>Persistency</code> («aapFunctionalCluster»): Realisiert die Schnittstelle <code>KeyValueStorage</code>.</li>\n<li><code>Cryptography</code> («aapFunctionalCluster», daemon-based): Realisiert die Schnittstelle <code>CryptoStack</code>.</li>\n</ul>\n<p class=\"fig-p\"><strong>Schnittstellen und Operationen:</strong></p>\n<ul class=\"fig-list\">\n<li><code>Raw Socket API</code> («aapInternal»): Interne OS-Schnittstelle ohne deklarierte Operationen.</li>\n<li><code>Logger</code> («aapAPI,aapNativeInterface»):</li>\n<li><code>+ IsEnabled(): bool</code></li>\n<li><code>+ Log(MsgId, Params)</code></li>\n<li><code>+ LogDebug(): LogStream</code></li>\n<li><code>+ LogError(): LogStream</code></li>\n<li><code>+ LogFatal(): LogStream</code></li>\n<li><code>+ LogInfo(): LogStream</code></li>\n<li><code>+ LogVerbose(): LogStream</code></li>\n<li><code>+ LogWarn(): LogStream</code></li>\n<li><code>+ WithLevel(): LogStream</code></li>\n<li><code>ExecutionClient</code> («aapAPI,aapNativeInterface»):</li>\n<li><code>+ Create()</code> (statische Methode / Factory)</li>\n<li><code>+ ReportExecutionState(ExecutionState)</code></li>\n<li><code>KeyValueStorage</code> («aapAPI,aapPortInterface»):</li>\n<li><code>+ DiscardPendingChanges()</code></li>\n<li><code>+ GetAllKeys()</code></li>\n<li><code>+ GetCurrentValueSize()</code></li>\n<li><code>+ GetValue()</code></li>\n<li><code>+ KeyExists()</code></li>\n<li><code>+ RecoverKey()</code></li>\n<li><code>+ RemoveAllKeys()</code></li>\n<li><code>+ RemoveKey()</code></li>\n<li><code>+ ResetKey()</code></li>\n<li><code>+ SetValue()</code></li>\n<li><code>+ SyncToStorage()</code></li>\n<li><code>CryptoStack</code> («aapAPI,aapNativeInterface»): Native Kryptografie-Schnittstelle ohne deklarierte Operationen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Architekturdiagramm ohne Darstellung von Laufzeitsequenzen oder Protokollabläufen. Die gerichteten «use»-Abhängigkeiten modellieren synchrone bzw. funktionale Aufrufbeziehungen vom <code>Time Synchronization</code>-Daemon in Richtung der Schnittstellen des Betriebssystems (<code>Raw Socket API</code> für Netzwerkzeit-Paketübertragung), des Loggings (<code>Logger</code> für Status- und Fehlerausgaben) und der Zustandsspeicherung (<code>KeyValueStorage</code> für persistente Zeitsynchronisationsparameter).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><code>Time Synchronization</code> bindet als Daemon-basierte Adaptive Application / Functional Cluster den <code>ExecutionClient</code> des <code>Execution Management</code> ein, um den eigenen Lebenszyklus und Prozesszustand (<code>ReportExecutionState</code>) im System zu melden.</li>\n<li><code>ExecutionClient::Create()</code> dient als Factory zur Instanziierung des Clients.</li>\n<li>Der Cluster stützt sich neben <code>Execution Management</code> auf <code>Cryptography</code> (native Krypto-Dienste), <code>Persistency</code> (Port-basiert via <code>KeyValueStorage</code>), <code>Log and Trace</code> (natives Logging) sowie das Betriebssystem (<code>Raw Socket API</code>).</li>\n</ul>"}], "trans": [{"from": "FIG-704f310fb3c34acb", "to": "FIG-9230af3e70a5249a", "fr": "R21-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-9230af3e70a5249a", "to": "FIG-9002b7d402773fe9", "fr": "R23-11", "tr": "R24-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Ergänzung des Functional Clusters <code>Cryptography</code> (daemon-based, «aapFunctionalCluster») mit Realisierung der Schnittstelle <code>CryptoStack</code> («aapAPI,aapNativeInterface»).</li>\n<li>Ergänzung der Abhängigkeit «use» von <code>Time Synchronization</code> auf <code>CryptoStack</code>.</li>\n<li>Ergänzung des Stereotyps «aapRequiredPort» an der «use»-Abhängigkeit von <code>Time Synchronization</code> zu <code>KeyValueStorage</code>.</li>\n<li>Schnittstelle <code>KeyValueStorage</code>: Methode <code>+ GetCurrentValueSize()</code> ergänzt; Klassenbezeichnung von <code>Persistency::KeyValueStorage</code> auf <code>KeyValueStorage</code> verkürzt.</li>\n<li>Schnittstelle <code>Logger</code>: Methoden-Signatur von <code>+ IsEnabled()</code> zu <code>+ IsEnabled(): bool</code> präzisiert; Klassenbezeichnung von <code>Log and Trace::Logger</code> auf <code>Logger</code> verkürzt.</li>\n</ul>"}, {"from": "FIG-9002b7d402773fe9", "to": "FIG-4975a7f23e5f4a80", "fr": "R24-11", "tr": "R25-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Ergänzung des Functional Clusters <code>Execution Management</code> (daemon-based, «aapFunctionalCluster»).</li>\n<li>Ergänzung der Schnittstelle <code>ExecutionClient</code> («aapAPI,aapNativeInterface») mit statischer Factory-Methode <code>+ Create()</code> und Methode <code>+ ReportExecutionState(ExecutionState)</code>.</li>\n<li>Ergänzung der Realisierungsbeziehung von <code>Execution Management</code> zu <code>ExecutionClient</code>.</li>\n<li>Ergänzung der Abhängigkeit «use» von <code>Time Synchronization</code> auf <code>ExecutionClient</code>.</li>\n</ul>"}]};
